389:   _star(x, r) {
390:     x.beginPath();
391:     for (let i = 0; i < 10; i++) {
392:       const a = -Math.PI / 2 + i * Math.PI / 5;
393:       const rad = i % 2 ? r * .42 : r;
394:       x[i ? 'lineTo' : 'moveTo'](Math.cos(a) * rad, Math.sin(a) * rad);
395:     }
396:     x.closePath(); x.fill();
397:   }
