399:   /* ------------------------------------------------------------ actors */
400:   _actors(x, game, cam) {
401:     if (!game || !game.ai) return;
402:     const ai = game.ai;
403:     const foxy = game.foxy || { stage: 0 };
404:     const posOf = a => (ai[a] ? ai[a].path[ai[a].index] : null);
405:     const on = (a, pos) => posOf(a) === pos;
406: 
407:     if (cam === '1A') {
408:       let spots = [];
409:       if (on('freddy', 'stage')) spots.push(['freddy', 384, 312, .95]);
410:       if (on('bonnie', 'stage')) spots.push(['bonnie', 258, 315, .9]);
411:       if (on('chica', 'stage')) spots.push(['chica', 512, 315, .9]);
412:       if (!spots.length) {
413:         // empty stage, curtains slightly parted
414:         x.fillStyle = 'rgba(0,0,0,.35)'; x.fillRect(300, 100, 168, 210);
415:       }
416:       for (const [type, sx, sy, s] of spots) this._char(x, type, sx, sy, s, 1);
417:     }
418:     if (cam === '1B') {
419:       const actors = [];
420:       if (on('freddy', 'dining')) actors.push(['freddy', 420, 330, .62]);
421:       if (on('bonnie', 'dining')) actors.push(['bonnie', 300, 300, .58]);
422:       if (on('chica', 'dining')) actors.push(['chica', 560, 345, .62]);
423:       for (const [type, sx, sy, s] of actors) this._char(x, type, sx, sy, s, 0);
424:     }
425:     if (cam === '1C') {
426:       const st = foxy.stage ?? 0;
427:       this._coveFoxy(x, st);
428:     }
429:     if (cam === '2A') {
430:       if (on('bonnie', 'westHall')) this._char(x, 'bonnie', 350, 330, .8, 0);
431:       if (game.foxy && game.foxy.running) this._char(x, 'foxy', 300 + Math.min(180, game.foxy.runT * 260), 340, .9, 0);
432:       if (on('bonnie', 'westCorner')) {
433:         // not here
434:       }
435:     }
436:     if (cam === '2B') {
437:       if (on('bonnie', 'westCorner')) this._char(x, 'bonnie', 320, 400, 1.4, 0, true);
438:       else if (game.foxy && game.foxy.running) this._char(x, 'foxy', 250 + Math.min(220, game.foxy.runT * 300), 410, 1.5, 0, true);
439:     }
440:     if (cam === '4A') {
441:       if (on('chica', 'eastHall')) this._char(x, 'chica', 430, 330, .8, 0);
442:       if (on('freddy', 'eastHall')) this._char(x, 'freddy', 360, 320, .82, 0);
443:     }
444:     if (cam === '4B') {
445:       if (on('chica', 'eastCorner')) this._char(x, 'chica', 430, 400, 1.4, 0, true);
446:       else if (on('freddy', 'eastCorner')) this._char(x, 'freddy', 400, 405, 1.45, 0, true);
447:     }
448:     if (cam === '5') {
449:       // eyes in the dark
450:       if (ai.freddy && ai.freddy.pos === 'stage' && Math.sin(this.t * .7) > .6) {
451:         x.fillStyle = 'rgba(255,220,150,.8)';
452:         x.beginPath(); x.arc(620, 170, 3, 0, 7); x.fill();
453:         x.beginPath(); x.arc(640, 170, 3, 0, 7); x.fill();
454:       }
455:     }
456:     if (cam === '3' && Math.sin(this.t * .33) > .93) {
457:       x.fillStyle = 'rgba(255,230,190,.75)';
458:       x.beginPath(); x.arc(500, 250, 2.5, 0, 7); x.fill();
459:       x.beginPath(); x.arc(516, 250, 2.5, 0, 7); x.fill();
460:     }
461:   }
