463:   _coveFoxy(x, stage) {
464:     const cx = W / 2, cy = 340;
465:     if (stage <= 0) {
466:       // closed curtain seam
467:       x.strokeStyle = 'rgba(0,0,0,.6)'; x.lineWidth = 4;
468:       x.beginPath(); x.moveTo(cx, 70); x.lineTo(cx, 360); x.stroke();
469:       return;
470:     }
471:     const gap = stage === 1 ? 14 : stage === 2 ? 70 : 170;
472:     // parted curtain
473:     x.fillStyle = '#050403';
474:     x.beginPath(); x.moveTo(cx - gap, 70); x.lineTo(cx + gap, 70); x.lineTo(cx + gap * .8, 370); x.lineTo(cx - gap * .8, 370); x.fill();
475:     // curtain edges
476:     for (const s of [-1, 1]) {
477:       const g = x.createLinearGradient(cx + s * gap, 0, cx + s * (gap + 40), 0);
478:       g.addColorStop(0, '#22122e'); g.addColorStop(1, '#4a2a62');
479:       x.fillStyle = g;
480:       x.beginPath();
481:       x.moveTo(cx + s * gap, 70); x.lineTo(cx + s * (gap + 46), 70);
482:       x.quadraticCurveTo(cx + s * (gap + 20), 220, cx + s * (gap + 40), 370);
483:       x.lineTo(cx + s * gap * .8, 370); x.fill();
484:     }
485:     if (stage === 1) {
486:       // eyes in the gap
487:       x.fillStyle = 'rgba(255,196,90,.9)';
488:       x.beginPath(); x.arc(cx - 4, 200, 2.2, 0, 7); x.fill();
489:       x.beginPath(); x.arc(cx + 4, 200, 2.2, 0, 7); x.fill();
490:     } else if (stage === 2) {
491:       this._char(x, 'foxy', cx, 400, 1.45, 2, true);
492:     } else {
493:       // gone — hook on the floor + open curtain
494:       x.fillStyle = 'rgba(0,0,0,.75)'; x.fillRect(cx - 80, 80, 160, 300);
495:       x.strokeStyle = '#8c887c'; x.lineWidth = 4;
496:       x.beginPath(); x.arc(cx + 12, 355, 14, .4, 4.2); x.stroke();
497:       x.fillStyle = 'rgba(230,215,185,.5)'; x.font = 'bold 10px "Courier New", monospace'; x.textAlign = 'center';
498:       x.fillText('IT\'S ME', cx, 150);
499:     }
500:   }
