502:   _char(x, type, sx, sy, s, variant = 0, close = false) {
503:     const pal = {
504:       freddy: ['#4b301c', '#7a5330', '#2a190d', '#9b7047', '#8f2b2a', '#e6efff'],
505:       bonnie: ['#3c3060', '#61508c', '#241c3c', '#7d6ba0', '#8c2b28', '#e4d6ff'],
506:       chica: ['#b08f32', '#d8b64c', '#7c621f', '#d3a53c', '#b5473a', '#d8c6ff'],
507:       foxy: ['#772b1d', '#a85f3e', '#4a1a12', '#b26743', '#171310', '#ffc95c']
508:     }[type];
509:     if (!pal) return;
510:     const [body, light, dark, muzzle, accent, eyeCol] = pal;
511:     const bob = Math.sin(this.t * 1.35 + sx * .031 + sy * .017) * (close ? 1.4 : 3.2);
512:     x.save();
513:     x.translate(sx, sy + bob);
514:     x.scale(s, s);
515: 
516:     // ground shadow
517:     x.fillStyle = 'rgba(0,0,0,.55)';
518:     x.beginPath(); x.ellipse(4, 2, 46, 10, 0, 0, 7); x.fill();
519:     // rim haze behind the silhouette
520:     const glow = x.createRadialGradient(0, -120, 8, 0, -120, 150);
521:     glow.addColorStop(0, close ? 'rgba(255,140,80,.14)' : 'rgba(255,190,120,.09)');
522:     glow.addColorStop(1, 'rgba(0,0,0,0)');
523:     x.fillStyle = glow; x.fillRect(-150, -270, 300, 290);
524: 
525:     // ---- legs
526:     x.fillStyle = dark;
527:     x.beginPath(); x.roundRect(-25, -62, 19, 52, 8); x.fill();
528:     x.beginPath(); x.roundRect(6, -62, 19, 52, 8); x.fill();
529:     x.fillStyle = '#1c1a16';
530:     for (const lx of [-22, 9]) {
531:       x.beginPath(); x.ellipse(lx + 6, -58, 7, 6, 0, 0, 7); x.fill();
532:       x.beginPath(); x.ellipse(lx + 6, -34, 6, 5, 0, 0, 7); x.fill();
533:     }
534:     x.fillStyle = body;
535:     x.beginPath(); x.ellipse(-16, -4, 17, 9, 0, 0, 7); x.fill();
536:     x.beginPath(); x.ellipse(18, -4, 17, 9, 0, 0, 7); x.fill();
537:     x.fillStyle = 'rgba(0,0,0,.25)';
538:     x.beginPath(); x.ellipse(-16, -1, 16, 5, 0, 0, 7); x.fill();
539:     x.beginPath(); x.ellipse(18, -1, 16, 5, 0, 0, 7); x.fill();
540: 
541:     // ---- arms
542:     for (const side of [-1, 1]) {
543:       x.save();
544:       x.translate(side * 39, -116);
545:       x.rotate(side * (.1 + Math.sin(this.t * .9 + sx * .02) * .018));
546:       const ag = x.createLinearGradient(-12, 0, 12, 0);
547:       ag.addColorStop(0, light); ag.addColorStop(.55, body); ag.addColorStop(1, dark);
548:       x.fillStyle = ag;
549:       x.beginPath(); x.roundRect(-11, 0, 22, 55, 10); x.fill();
550:       x.fillStyle = '#22201b';
551:       x.beginPath(); x.arc(0, 54, 8, 0, 7); x.fill();
552:       x.fillStyle = body;
553:       x.beginPath(); x.roundRect(-9, 56, 18, 34, 8); x.fill();
554:       if (type === 'foxy' && side > 0) {
555:         x.strokeStyle = '#9b988c'; x.lineWidth = 4;
556:         x.beginPath(); x.arc(0, 96, 11, .3, 4.5); x.stroke();
557:       } else {
558:         x.fillStyle = dark;
559:         x.beginPath(); x.ellipse(0, 96, 10, 9, 0, 0, 7); x.fill();
560:         // fingers
561:         x.fillStyle = body;
562:         for (let f = 0; f < 3; f++) {
563:           x.beginPath(); x.roundRect(-8 + f * 6, 98, 5, 13, 2.5); x.fill();
564:         }
565:       }
566:       x.restore();
567:     }
568: 
569:     // ---- torso
570:     const tg = x.createLinearGradient(-42, -140, 42, -62);
571:     tg.addColorStop(0, light);
572:     tg.addColorStop(.4, body);
573:     tg.addColorStop(1, dark);
574:     x.fillStyle = tg;
575:     x.beginPath();
576:     x.moveTo(-37, -128);
577:     x.bezierCurveTo(-46, -103, -38, -75, -25, -60);
578:     x.lineTo(25, -60);
579:     x.bezierCurveTo(38, -75, 46, -103, 37, -128);
580:     x.bezierCurveTo(26, -142, -26, -142, -37, -128);
581:     x.closePath();
582:     x.fill();
583:     // shoulder caps
584:     x.fillStyle = dark;
585:     x.beginPath(); x.ellipse(-38, -125, 12, 14, -.2, 0, 7); x.fill();
586:     x.beginPath(); x.ellipse(38, -125, 12, 14, .2, 0, 7); x.fill();
587:     // belly plate
588:     const bg = x.createLinearGradient(0, -125, 0, -66);
589:     bg.addColorStop(0, light); bg.addColorStop(.5, muzzle); bg.addColorStop(1, dark);
590:     x.fillStyle = bg;
591:     x.beginPath(); x.ellipse(0, -93, 24, 33, 0, 0, 7); x.fill();
592:     x.strokeStyle = 'rgba(255,240,210,.16)'; x.lineWidth = 1.5;
593:     x.beginPath(); x.ellipse(0, -93, 24, 33, 0, 0, 7); x.stroke();
594:     // torso seam
595:     x.strokeStyle = 'rgba(0,0,0,.35)'; x.lineWidth = 1.5;
596:     x.beginPath(); x.moveTo(-27, -118); x.quadraticCurveTo(0, -108, 27, -118); x.stroke();
597:     // bow tie
598:     if (type !== 'foxy') {
599:       x.fillStyle = accent;
600:       for (const side of [-1, 1]) {
601:         x.beginPath();
602:         x.moveTo(side * 2, -130); x.lineTo(side * 17, -137); x.lineTo(side * 17, -123); x.closePath(); x.fill();
603:       }
604:       x.beginPath(); x.arc(0, -130, 4, 0, 7); x.fill();
605:     }
606:     // buttons
607:     x.fillStyle = 'rgba(20,16,12,.7)';
608:     x.beginPath(); x.arc(0, -112, 2.4, 0, 7); x.fill();
609:     x.beginPath(); x.arc(0, -103, 2.4, 0, 7); x.fill();
610: 
611:     // ---- head (ears/hat behind skull)
612:     const hy = -172;
613:     if (type === 'freddy') {
614:       x.fillStyle = body;
615:       for (const side of [-1, 1]) {
616:         x.beginPath(); x.arc(side * 28, hy - 20, 12, 0, 7); x.fill();
617:         x.fillStyle = dark;
618:         x.beginPath(); x.arc(side * 28, hy - 20, 6, 0, 7); x.fill();
619:         x.fillStyle = body;
620:       }
621:       x.fillStyle = '#111010';
622:       x.fillRect(-17, hy - 47, 34, 19);
623:       x.beginPath(); x.ellipse(0, hy - 28, 27, 5.5, 0, 0, 7); x.fill();
624:       x.fillStyle = '#6e1f18';
625:       x.fillRect(-16, hy - 35, 32, 4);
626:     } else if (type === 'bonnie') {
627:       x.fillStyle = body;
628:       for (const side of [-1, 1]) {
629:         x.save(); x.translate(side * 15, hy - 35); x.rotate(side * .12);
630:         x.beginPath(); x.ellipse(0, -12, 8, 30, 0, 0, 7); x.fill();
631:         x.fillStyle = muzzle;
632:         x.beginPath(); x.ellipse(0, -10, 3.5, 20, 0, 0, 7); x.fill();
633:         x.restore();
634:         x.fillStyle = body;
635:       }
636:     } else if (type === 'chica') {
637:       x.fillStyle = body;
638:       x.beginPath(); x.moveTo(-10, hy - 23); x.quadraticCurveTo(-4, hy - 55, 6, hy - 30); x.fill();
639:       x.beginPath(); x.moveTo(10, hy - 23); x.quadraticCurveTo(16, hy - 48, 22, hy - 25); x.fill();
640:     } else {
641:       x.fillStyle = body;
642:       for (const side of [-1, 1]) {
643:         x.beginPath(); x.moveTo(side * 18, hy - 12); x.lineTo(side * 34, hy - 46); x.lineTo(side * 36, hy - 12); x.closePath(); x.fill();
644:         x.fillStyle = dark;
645:         x.beginPath(); x.moveTo(side * 24, hy - 17); x.lineTo(side * 32, hy - 39); x.lineTo(side * 32, hy - 17); x.closePath(); x.fill();
646:         x.fillStyle = body;
647:       }
648:     }
649: 
650:     // skull
651:     const hg = x.createRadialGradient(-10, hy - 8, 4, 0, hy, 42);
652:     hg.addColorStop(0, light); hg.addColorStop(.52, body); hg.addColorStop(1, dark);
653:     x.fillStyle = hg;
654:     x.beginPath(); x.ellipse(0, hy, 33, 31, 0, 0, 7); x.fill();
655:     // side shading
656:     const shade = x.createLinearGradient(14, hy - 30, 34, hy + 20);
657:     shade.addColorStop(0, 'rgba(0,0,0,0)'); shade.addColorStop(1, 'rgba(0,0,0,.45)');
658:     x.fillStyle = shade;
659:     x.beginPath(); x.ellipse(0, hy, 33, 31, 0, 0, 7); x.fill();
660: 
661:     // muzzle / beak
662:     if (type === 'chica') {
663:       const bkg = x.createLinearGradient(0, hy + 4, 0, hy + 28);
664:       bkg.addColorStop(0, '#f0a23a'); bkg.addColorStop(1, '#b86a18');
665:       x.fillStyle = bkg;
666:       x.beginPath(); x.moveTo(-16, hy + 7); x.lineTo(16, hy + 7); x.lineTo(0, hy + 29); x.closePath(); x.fill();
667:       x.strokeStyle = 'rgba(90,50,10,.7)'; x.lineWidth = 1.5; x.stroke();
668:     } else {
669:       const mg = x.createLinearGradient(0, hy - 2, 0, hy + 24);
670:       mg.addColorStop(0, muzzle); mg.addColorStop(1, dark);
671:       x.fillStyle = mg;
672:       x.beginPath(); x.ellipse(0, hy + 13, 21, 13, 0, 0, 7); x.fill();
673:       if (type === 'foxy') {
674:         x.beginPath(); x.ellipse(0, hy + 15, 16, 14, 0, 0, 7); x.fill();
675:       }
676:       // nose
677:       x.fillStyle = '#1c1410';
678:       x.beginPath(); x.ellipse(0, hy + 4, 5.5, 4, 0, 0, 7); x.fill();
679:     }
680: 
681:     // mouth / jaw
682:     const jawOpen = close ? 8 : 2 + Math.sin(this.t * 1.5 + sx) * 1.2;
683:     x.fillStyle = '#0b0605';
684:     x.beginPath(); x.ellipse(0, hy + 18 + jawOpen * .3, 15, 5 + jawOpen * .35, 0, 0, 7); x.fill();
685:     // teeth
686:     x.fillStyle = '#ddd3b9';
687:     for (let i = -2; i <= 2; i++) {
688:       x.fillRect(i * 5 - 1.4, hy + 13 + jawOpen * .2, 3, 4.5);
689:       x.fillRect(i * 5 - 1.4, hy + 22 + jawOpen * .55, 3, 4);
690:     }
691: 
692:     // eyes — sunken sockets, bright irises
693:     for (const side of [-1, 1]) {
694:       x.fillStyle = '#1a140f';
695:       x.beginPath(); x.ellipse(side * 12, hy - 5, 9.5, 8.5, 0, 0, 7); x.fill();
696:       x.fillStyle = type === 'foxy' ? '#efe5cd' : '#e8e0cc';
697:       x.beginPath(); x.ellipse(side * 12, hy - 5, 7, 6.3, 0, 0, 7); x.fill();
698:       x.fillStyle = eyeCol;
699:       x.shadowColor = eyeCol; x.shadowBlur = close ? 16 : 10;
700:       x.beginPath(); x.arc(side * 12, hy - 5, close ? 3.6 : 3, 0, 7); x.fill();
701:       x.shadowBlur = 0;
702:       x.fillStyle = '#080605';
703:       x.beginPath(); x.arc(side * 12, hy - 5, 1.5, 0, 7); x.fill();
704:       x.fillStyle = 'rgba(255,250,235,.85)';
705:       x.beginPath(); x.arc(side * 12 - 1.2, hy - 6.6, .9, 0, 7); x.fill();
706:       // angry brow
707:       x.strokeStyle = 'rgba(15,10,7,.85)'; x.lineWidth = 2.6;
708:       x.beginPath();
709:       x.moveTo(side * 18, hy - 17); x.lineTo(side * 6, hy - 12);
710:       x.stroke();
711:     }
712:     // Foxy eyepatch
713:     if (type === 'foxy') {
714:       x.fillStyle = '#0d0b09';
715:       x.beginPath(); x.ellipse(-12, hy - 5, 9, 8, 0, 0, 7); x.fill();
716:       x.strokeStyle = '#0d0b09'; x.lineWidth = 2;
717:       x.beginPath(); x.moveTo(-24, hy - 14); x.lineTo(24, hy - 20); x.stroke();
718:     }
719:     // Chica bib
720:     if (type === 'chica') {
721:       x.fillStyle = '#ece4d0';
722:       x.beginPath(); x.ellipse(0, -132, 17, 12, -.1, 0, 7); x.fill();
723:       x.fillStyle = '#b5473a'; x.font = 'bold 6px Georgia, serif'; x.textAlign = 'center';
724:       x.fillText('LET\'S EAT', 0, -130);
725:     }
726:     // cheek highlights
727:     x.fillStyle = 'rgba(255,240,210,.08)';
728:     x.beginPath(); x.ellipse(-18, hy - 16, 8, 12, -.3, 0, 7); x.fill();
729: 
730:     // overall lower-body shade for depth
731:     const lower = x.createLinearGradient(0, -150, 0, 0);
732:     lower.addColorStop(0, 'rgba(0,0,0,0)');
733:     lower.addColorStop(.7, 'rgba(0,0,0,.18)');
734:     lower.addColorStop(1, 'rgba(0,0,0,.42)');
735:     x.fillStyle = lower;
736:     x.fillRect(-50, -155, 100, 158);
737: 
738:     x.restore();
