741:   /* ------------------------------------------------------------ fx overlay */
742:   _overlay(x, game) {
743:     const t = this.t;
744:     // noise specks
745:     x.globalAlpha = .10 + Math.random() * .03;
746:     x.drawImage(this.noise, Math.random() * 60, Math.random() * 60, 768, 432);
747:     x.globalAlpha = 1;
748:     // static bands
