533:   const w = 256, h = 256, c = canvas(w, h), x = c.getContext('2d');
534:   const base = '#' + (hex >>> 0).toString(16).padStart(6, '0');
535:   x.fillStyle = base; x.fillRect(0, 0, w, h);
536:   // soft blotches of dirt and wear
537:   for (let i = 0; i < 46; i++) {
538:     const gx = rand() * w, gy = rand() * h, r = 6 + rand() * 40;
539:     const g = x.createRadialGradient(gx, gy, 0, gx, gy, r);
540:     const dark = rand() > .35;
541:     g.addColorStop(0, dark ? `rgba(20,14,8,${.05 + rand() * .12})` : `rgba(255,230,190,${.03 + rand() * .06})`);
542:     g.addColorStop(1, 'rgba(0,0,0,0)');
543:     x.fillStyle = g; x.fillRect(gx - r, gy - r, r * 2, r * 2);
544:   }
545:   // fabric noise
546:   const img = x.getImageData(0, 0, w, h);
547:   for (let i = 0; i < img.data.length; i += 4) {
548:     const n = (rand() - .5) * 17;
549:     img.data[i] += n; img.data[i + 1] += n; img.data[i + 2] += n;
550:   }
551:   x.putImageData(img, 0, 0);
552:   // seams
553:   x.strokeStyle = 'rgba(20,12,6,.22)'; x.lineWidth = 2;
554:   x.beginPath(); x.moveTo(w * .5, 0); x.lineTo(w * .5, h); x.stroke();
555:   x.beginPath(); x.moveTo(0, h * .62); x.lineTo(w, h * .62); x.stroke();
556:   x.strokeStyle = 'rgba(255,225,180,.06)'; x.lineWidth = 1;
557:   x.beginPath(); x.moveTo(w * .5 + 2, 0); x.lineTo(w * .5 + 2, h); x.stroke();
558:   scratches(x, w, h, 26, 'rgba(255,240,210,.05)');
559:   grime(x, w, h, 14, 'rgba(12,8,4,');
560:   const t = finish(c, 2, 2);
561:   suitCache.set(hex, t);
562:   return t;
563: }
