693: /* ---------------------------------------------------------- bump maps */
694: const bumpCache = new Map();
695: export function bumpTexture(kind = 'plaster') {
696:   if (bumpCache.has(kind)) return bumpCache.get(kind);
697:   const w = 256, h = 256, c = canvas(w, h), x = c.getContext('2d');
698:   x.fillStyle = '#808080'; x.fillRect(0, 0, w, h);
699:   if (kind === 'plaster') {
700:     for (let i = 0; i < 900; i++) {
701:       const a = (rand() - .5) * 16;
702:       const v = Math.max(0, Math.min(255, 128 + a));
703:       x.fillStyle = `rgba(${v},${v},${v},${.15 + rand() * .2})`;
704:       x.fillRect(rand() * w, rand() * h, 1 + rand() * 4, 1 + rand() * 2);
705:     }
706:     // trowel arcs
707:     x.lineWidth = 2;
708:     for (let i = 0; i < 13; i++) {
709:       x.strokeStyle = `rgba(${rand() > .5 ? 150 : 96},${rand() > .5 ? 150 : 96},120,.12)`;
710:       x.beginPath(); x.arc(rand() * w, rand() * h, 12 + rand() * 44, rand() * 6, rand() * 6); x.stroke();
711:     }
712:   } else if (kind === 'tile') {
713:     const n = 4, s = w / n;
714:     for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
715:       const v = 132 + ((i + j) % 2 ? -6 : 6);
716:       x.fillStyle = `rgb(${v},${v},${v})`;
717:       x.fillRect(i * s + 2, j * s + 2, s - 4, s - 4);
718:     }
719:     x.strokeStyle = '#4a4a4a'; x.lineWidth = 3;
720:     for (let i = 0; i <= n; i++) {
721:       x.beginPath(); x.moveTo(i * s, 0); x.lineTo(i * s, h); x.stroke();
722:       x.beginPath(); x.moveTo(0, i * s); x.lineTo(w, i * s); x.stroke();
723:     }
724:   } else if (kind === 'wood') {
725:     for (let i = 0; i < 90; i++) {
726:       const y = rand() * h;
727:       x.strokeStyle = `rgba(${rand() > .5 ? 158 : 94},${rand() > .5 ? 158 : 94},${rand() > .5 ? 158 : 94},${.12 + rand() * .24})`;
728:       x.lineWidth = .5 + rand() * 1.6;
729:       x.beginPath(); x.moveTo(0, y);
730:       x.bezierCurveTo(w * .3, y + (rand() - .5) * 14, w * .6, y + (rand() - .5) * 14, w, y + (rand() - .5) * 8);
731:       x.stroke();
732:     }
733:   } else if (kind === 'metal') {
734:     for (let y = 0; y < h; y += 32) {
735:       x.fillStyle = '#a0a0a0'; x.fillRect(0, y, w, 26);
736:       x.fillStyle = '#555'; x.fillRect(0, y + 26, w, 6);
737:       x.fillStyle = '#c8c8c8'; x.fillRect(0, y, w, 2);
738:     }
739:     for (let y = 16; y < h; y += 64) {
740:       x.fillStyle = '#3a3a3a';
741:       for (const bx of [16, w - 16]) { x.beginPath(); x.arc(bx, y, 3, 0, 7); x.fill(); }
742:     }
743:   } else if (kind === 'fabric') {
744:     for (let i = 0; i < w; i += 4) {
745:       x.fillStyle = 'rgba(110,110,110,.35)'; x.fillRect(i, 0, 1, h);
746:       x.fillStyle = 'rgba(150,150,150,.22)'; x.fillRect(0, i, w, 1);
747:     }
748:     for (let i = 0; i < 110; i++) {
749:       const v = 128 + (rand() - .5) * 40;
750:       x.fillStyle = `rgba(${v},${v},${v},.18)`;
751:       x.fillRect(rand() * w, rand() * h, 1 + rand() * 3, 1 + rand() * 3);
752:     }
753:   } else {
754:     for (let i = 0; i < 500; i++) {
755:       const v = 128 + (rand() - .5) * 46;
756:       x.fillStyle = `rgba(${v},${v},${v},.2)`;
757:       x.fillRect(rand() * w, rand() * h, 1 + rand() * 3, 1 + rand() * 3);
758:     }
759:   }
760:   const t = new THREE.CanvasTexture(c);
761:   t.wrapS = t.wrapT = THREE.RepeatWrapping;
762:   t.anisotropy = 4;
763:   const reps = { tile: [4, 4], wood: [2, 2], metal: [1, 3], fabric: [2, 2], plaster: [2, 2] };
764:   const r = reps[kind] || [2, 2];
765:   t.repeat.set(r[0], r[1]);
766:   bumpCache.set(kind, t);
767:   return t;
768: }

