204:       const g = new THREE.Group();
205:       const lower = box(w, .92, .08, wains, 0, .46, 0);
206:       lower.receiveShadow = true;
207:       g.add(lower);
208:       const upperH = wallH - .92;
209:       const upper = plane(w, upperH, wall, 0, .92 + upperH / 2, .041);
210:       g.add(upper);
211:       const rail = box(w, .07, .13, trim, 0, .94, .04);
212:       g.add(rail);
213:       const base = box(w, .14, .1, trim, 0, .07, .04);
214:       g.add(base);
215:       return g;
216:     };
217: 
218:     // front wall (behind desk) at z = front
219:     const fw = buildWall(OFFICE.w * 2);
220:     fw.position.set(0, 0, OFFICE.front);
221:     this.office.add(fw);
222: 
223:     // back wall (behind player)
224:     const bw = buildWall(OFFICE.w * 2);
225:     bw.position.set(0, 0, OFFICE.back);
226:     bw.rotation.y = Math.PI;
227:     this.office.add(bw);
228: 
229:     // side walls with door openings
230:     const zA = OFFICE.front, zB = OFFICE.doorZ - OFFICE.doorW / 2;
231:     const zC = OFFICE.doorZ + OFFICE.doorW / 2, zD = OFFICE.back;
232:     const upperH = OFFICE.h - .92;
233:     for (const side of [-1, 1]) {
234:       const x = side * OFFICE.w;
235:       const ry = side < 0 ? Math.PI / 2 : -Math.PI / 2;
236:       const segs = [[zA, zB], [zC, zD]];
237:       for (const [za, zb] of segs) {
238:         const len = Math.abs(zb - za), cz = (za + zb) / 2;
239:         const lower = plane(len, .92, wains, x, .46, cz, 0, ry);
240:         lower.receiveShadow = true;
241:         const upper = plane(len, upperH, wall, x, .92 + upperH / 2, cz, 0, ry);
242:         upper.receiveShadow = true;
243:         this.office.add(lower, upper);
244:         this.office.add(box(.1, .07, len, trim, x, .945, cz));
245:         this.office.add(box(.1, .15, len, trim, x, .075, cz));
246:       }
247:       // header above the doorway
248:       const headerH = OFFICE.h - OFFICE.doorH;
249:       this.office.add(plane(OFFICE.doorW, headerH, wall, x, OFFICE.doorH + headerH / 2, OFFICE.doorZ, 0, ry));
250:       this.office.add(box(.1, .1, OFFICE.doorW + .2, trim, x, OFFICE.doorH + headerH - .05, OFFICE.doorZ));
251:     }
252: 
253:     // door frames + shutters + hall
254:     for (const side of [-1, 1]) {
255:       const key = side < 0 ? 'left' : 'right';
256:       // frame
257:       const frameM = mat({ color: 0x3a3126, roughness: .5, metalness: .5 });
258:       const frame = new THREE.Group();
259:       frame.add(box(.13, OFFICE.doorH + .08, .12, frameM, 0, OFFICE.doorH / 2, -OFFICE.doorW / 2 - .05));
260:       frame.add(box(.13, OFFICE.doorH + .08, .12, frameM, 0, OFFICE.doorH / 2, OFFICE.doorW / 2 + .05));
261:       frame.add(box(.13, .14, OFFICE.doorW + .22, frameM, 0, OFFICE.doorH + .04, 0));
262:       frame.position.set(side * OFFICE.w, 0, OFFICE.doorZ);
263:       frame.rotation.y = side * Math.PI / 2;
264:       this.office.add(frame);
265: 
266:       // hazard threshold plate
267:       const hazardMat = new THREE.MeshStandardMaterial({ map: hazardTexture(), roughness: .82 });
268:       const threshold = plane(.13, OFFICE.doorW + .1, hazardMat, side * (OFFICE.w - .13), .012, OFFICE.doorZ, -Math.PI / 2);
269:       this.office.add(threshold);
270:       const warning = plane(.42, .1, new THREE.MeshStandardMaterial({ map: hazardTexture(), roughness: .8 }), side * (OFFICE.w - .06), OFFICE.doorH + .34, OFFICE.doorZ, 0, side < 0 ? Math.PI / 2 : -Math.PI / 2);
271:       this.office.add(warning);
272: 
273:       // shutter — slides in Y
274:       const shutter = box(.1, OFFICE.doorH + .06, OFFICE.doorW + .04, metal, 0, OFFICE.doorH / 2, 0);
275:       shutter.castShadow = true; shutter.receiveShadow = true;
276:       const sg = new THREE.Group();
277:       sg.position.set(side * OFFICE.w, 0, OFFICE.doorZ);
278:       sg.rotation.y = side * Math.PI / 2;
279:       sg.add(shutter);
280:       shutter.position.y = OFFICE.doorH / 2 + 2.4;
281:       this.office.add(sg);
282:       // warning light strip above door
283:       const strip = box(.05, .035, OFFICE.doorW * .8, new THREE.MeshBasicMaterial({ color: 0x52140f, transparent: true, opacity: .9 }), 0, OFFICE.doorH + .13, 0);
284:       sg.add(strip);
285: 
286:       // button panel (visual only)
287:       const panel = new THREE.Group();
288:       const pm = mat({ color: 0x2b2823, roughness: .6, metalness: .3 });
289:       panel.add(box(.05, .54, .3, pm, 0, 0, 0));
290:       const b1 = box(.03, .1, .11, mat({ color: 0xa8352c, emissive: 0x320704, emissiveIntensity: .5, roughness: .4 }), -.03, .11, 0);
291:       const b2 = box(.03, .1, .11, mat({ color: 0xd0a04a, emissive: 0x2a1a02, emissiveIntensity: .4, roughness: .4 }), -.03, -.11, 0);
292:       panel.add(b1, b2);
293:       panel.position.set(side * (OFFICE.w - .17), 1.34, OFFICE.doorZ + .92);
294:       panel.rotation.y = -side * Math.PI / 2;
295:       this.office.add(panel);
296:       this.doors = this.doors || {};
297:       this.doors[key] = { shutter, group: sg, strip, b1, b2 };
298: 
299:       // hall
300:       this._buildHall(side, key, floorM, wall, wains, trim, ceil);
301:     }
302: 
303:     // baseboards/ceiling strip
304:     this.office.add(box(OFFICE.w * 2, .08, .08, trim, 0, OFFICE.h - .04, OFFICE.front + .04));
305:     this.office.add(box(OFFICE.w * 2, .08, .08, trim, 0, OFFICE.h - .04, OFFICE.back - .04));
306: 
307:     this._buildLights();
308:     this._buildDesk();
309:     this._buildFrontWall();
310:     this._buildBackWall();
311:     this._buildDust();
312:     this._buildOfficeDetails();
