import { createRequire } from 'node:module';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');

const URL = process.env.URL || 'http://127.0.0.1:4180/';
const OUT = '/home/runner/work/Fnafv2/Fnafv2/screenshots';

const browser = await chromium.launch({
  headless: true,
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-gpu-sandbox']
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR', e.message); });
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto(URL, { waitUntil: 'load', timeout: 60000 });
await page.locator('#boot-start').waitFor({ state: 'visible', timeout: 60000 });
await page.click('#boot-start');
await page.locator('#menu:not(.hidden)').waitFor({ timeout: 15000 });
await page.click('#start-night');
await page.waitForFunction(() => window.__fnf?.game?.state === 'playing', null, { timeout: 30000 });
await page.waitForTimeout(700);

// freeze the sim and stage a character in the left doorway
await page.evaluate(() => {
  const { game, world } = window.__fnf;
  game.startDelay = 9999;
  game.power = 100;
  for (const k in game.ai) { game.ai[k].atDoor = false; game.ai[k].attackT = 9999; }
  game.ai.bonnie.atDoor = true;
  game.ai.bonnie.side = 'left';
  game.ai.bonnie.attackT = 9999;
  game.lights.left = true;
  game.lights.right = false;
  game.doors.left = false;
  game.doors.right = false;
  world.targetYaw = -0.70;
  world.targetPitch = -0.035;
  world.yaw = -0.70;
  world.pitch = -0.035;
});
await page.waitForTimeout(1200);
await page.screenshot({ path: OUT + '/fix-left-lit.jpg', quality: 90, type: 'jpeg' });

// right doorway
await page.evaluate(() => {
  const { game, world } = window.__fnf;
  game.ai.bonnie.atDoor = false;
  game.ai.chica.atDoor = true;
  game.ai.chica.side = 'right';
  game.ai.chica.attackT = 9999;
  game.lights.left = false;
  game.lights.right = true;
  world.targetYaw = 0.70;
  world.targetPitch = -0.035;
  world.yaw = 0.70;
  world.pitch = 0.035;
});
await page.waitForTimeout(1400);
await page.screenshot({ path: OUT + '/fix-right-lit.jpg', quality: 90, type: 'jpeg' });

// close the right shutter on the character
await page.evaluate(() => {
  const { game, world } = window.__fnf;
  game.doors.right = true;
  world.setDoor('right', true);
  world.targetYaw = 0.70;
});
await page.waitForTimeout(900);
await page.screenshot({ path: OUT + '/fix-right-closed.jpg', quality: 90, type: 'jpeg' });

// report geometry / visibility state
const info = await page.evaluate(() => {
  const { game, world } = window.__fnf;
  const d = world.doors;
  const c = world._officeChars || {};
  return {
    state: game.state,
    door: d.right.shutter.position.y,
    shutterSize: [d.right.shutter.geometry.parameters.width, d.right.shutter.geometry.parameters.height, d.right.shutter.geometry.parameters.depth],
    frameRot: d.right.frame.rotation.y,
    groupRot: d.right.group.rotation.y,
    bonnie: c.bonnie && { pos: c.bonnie.group.position.toArray(), rot: c.bonnie.group.rotation.y, visible: c.bonnie.group.visible },
    chica: c.chica && { pos: c.chica.group.position.toArray(), rot: c.chica.group.rotation.y, visible: c.chica.group.visible },
    lights: { left: world.light.left, right: world.light.right },
    reveal: d.right.revealLight.intensity,
    drawCalls: world.renderer.info.render.calls,
    triangles: world.renderer.info.render.triangles
  };
});
console.log(JSON.stringify(info, null, 2));

// mobile portrait
