import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const URL = 'http://127.0.0.1:4180/';
const OUT = '/home/runner/work/Fnafv2/Fnafv2/screenshots';
const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errs = [];
page.on('pageerror', e => { errs.push(e.message); console.log('PAGEERROR', e.message); });
await page.goto(URL, { waitUntil: 'load', timeout: 60000 });
await page.locator('#boot-start').waitFor({ state: 'visible', timeout: 60000 });
await page.evaluate(() => window.__fnf.world.setPixelRatio(.7));
await page.evaluate(() => document.querySelector('#boot-start').click());
await page.locator('#menu:not(.hidden)').waitFor({ timeout: 20000 });
await page.waitForTimeout(1500);
await page.screenshot({ path: OUT + '/hd-menu.jpg', quality: 88, type: 'jpeg', timeout: 120000 });

await page.evaluate(() => document.querySelector('#start-night').click());
await page.locator('#intro-go').waitFor({ state: 'visible', timeout: 20000 });
await page.evaluate(() => document.querySelector('#intro-go').click());
await page.waitForFunction(() => window.__fnf.getState() === 'playing', null, { timeout: 30000 });
await page.waitForTimeout(1500);
await page.evaluate(() => window.__fnf.world.setPixelRatio(.9));
await page.screenshot({ path: OUT + '/hd-office.jpg', quality: 88, type: 'jpeg', timeout: 120000 });

// stage Bonnie at the west door, lights on
await page.evaluate(() => {
  const { game, world } = window.__fnf;
  game.startDelay = 9999;
  for (const k in game.ai) { game.ai[k].atDoor = false; game.ai[k].attackT = 9999; }
  game.ai.bonnie.atDoor = true;
  game.ai.bonnie.side = 'left';
  game.ai.bonnie.attackT = 9999;
  game.lights.left = true;
  game.lights.right = false;
  game.doors.left = false;
  world.targetYaw = 0.70; world.yaw = 0.70;
  world.targetPitch = -0.03; world.pitch = -0.03;
});
await page.waitForTimeout(1600);
await page.screenshot({ path: OUT + '/hd-left-reveal.jpg', quality: 88, type: 'jpeg', timeout: 120000 });

// close the left door and turn the light off to check the shutter read
await page.evaluate(() => {
  const { game, world } = window.__fnf;
  game.doors.left = true;
  game.lights.left = true;
  world.setDoor('left', true);
  world.targetYaw = 0.70;
});
await page.waitForTimeout(1300);
await page.screenshot({ path: OUT + '/hd-left-closed.jpg', quality: 88, type: 'jpeg', timeout: 120000 });

// Foxy sprint near the door
await page.evaluate(() => {
  const { world } = window.__fnf;
  world.setCornerCharacter('left', null);
  world.setFoxyRunning(true, .92);
  world.targetYaw = 0.70; world.yaw = 0.70;
});
await page.waitForTimeout(800);
await page.screenshot({ path: OUT + '/hd-foxy.jpg', quality: 88, type: 'jpeg', timeout: 120000 });

console.log('ERRORS', errs.length ? errs : 'none');
await browser.close();

