import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const OUT = '/home/runner/work/Fnafv2/Fnafv2/screenshots';
const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1024, height: 640 } });
const errs = []; page.on('pageerror', e => { errs.push(e.message); console.log('ERR', e.message); });
await page.goto('http://127.0.0.1:4180/', { waitUntil: 'load', timeout: 60000 });
await page.locator('#boot-start').waitFor({ state: 'visible', timeout: 60000 });
await page.evaluate(() => window.__fnf.world.setPixelRatio(.65));
await page.evaluate(() => document.querySelector('#boot-start').click());
await page.locator('#menu:not(.hidden)').waitFor({ timeout: 20000 });
await page.evaluate(() => document.querySelector('#start-night').click());
await page.locator('#intro-go').waitFor({ state: 'visible', timeout: 20000 });
await page.evaluate(() => document.querySelector('#intro-go').click());
await page.waitForFunction(() => window.__fnf.getState() === 'playing', null, { timeout: 30000 });
await page.waitForTimeout(600);
await page.evaluate(() => {
  const { game, world } = window.__fnf;
  game.state = 'paused';
  game.lights.left = true;
  game.doors.left = true;
  world.setLight('left', true);
  world.setDoor('left', true);
  world.lookEnabled = false;
  world.camera.position.set(-1.15, 1.62, 0.15);
  world.yaw = 1.22; world.targetYaw = 1.22;
  world.pitch = -0.24; world.targetPitch = -0.24;
});
await page.waitForTimeout(1500);
await page.screenshot({ path: OUT + '/hd-door-closeup.jpg', quality: 90, type: 'jpeg', timeout: 120000 });

// open door with Bonnie
await page.evaluate(() => {
  const { game, world } = window.__fnf;
  game.doors.left = false;
  game.ai.bonnie.atDoor = true; game.ai.bonnie.side = 'left';
  world.setDoor('left', false);
  world.setCornerCharacter('left', 'bonnie');
});
await page.waitForTimeout(1200);
await page.screenshot({ path: OUT + '/hd-door-open-closeup.jpg', quality: 90, type: 'jpeg', timeout: 120000 });
console.log('ERRORS', errs.length ? errs : 'none');
await browser.close();

